import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as A,S as c}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"帧与 MAC","description":"","frontmatter":{"title":"帧与 MAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/frame-mac.md","filePath":"cs/frame-mac.md","lastUpdated":1789023840000}'),p={name:"cs/frame-mac.md"};function E(m,a,B,h,C,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="帧与-mac" tabindex="-1">帧与 MAC <a class="header-anchor" href="#帧与-mac" aria-label="Permalink to &quot;帧与 MAC&quot;">​</a></h1><div class="epigraph"><p>链路上传送的是帧：目的与源的硬件地址、类型、载荷与校验；MAC 决定谁在何时占用介质。</p><footer>—— 据 Metcalfe and Boggs, Ethernet: Distributed Packet Switching for Local Computer Networks, CACM 1976；IEEE 802 整理</footer></div><p><a href="/cs/five-vs-four-layer">上一课</a>给出分层与端到端，还没有一跳的 PDU。<a href="/cs/io-dma">I/O 与 DMA</a> 能把网卡缓冲搬进内存，但缓冲里的位如何被邻机认成「给我的」。缺口是<strong>帧</strong>与 <strong>MAC 地址</strong>：链路层的名字，只在这一跳有效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播介质上，所有网卡都可能看见电信号。若没有目的地址，每台主机都要把噪声当数据。以太网风格：48 位 MAC、帧头、载荷（后课的 IP 包放这里）、FCS。网卡用 DMA 收齐一帧，用地址过滤：不是自己且不是广播/组播则丢。缺口不是 IP 路由，而是这一跳的命名与成帧。</p><p>本课不把 CSMA 退避算法写完，那是下一课。</p><p><span class="marginnote">MAC 地址由厂商与全局/本地位组成，链路层当扁平标识用。它不是地理位置，也不能代替 IP 的跨网编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：上层交出载荷，驱动加上目的/源 MAC 与以太类型，算 FCS，经 DMA 出门。接收：FCS 错则丢（链路努力，不是端到端保证）；类型字段交给 IP 或其他。点到点链路（PPP）帧格式不同，对象仍是「一跳 PDU + 校验」。</p>',9)),(e(),n(c,null,{default:r(()=>[A(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAY%5B%22%E7%BD%91%E7%BB%9C%E5%B1%82%E8%BD%BD%E8%8D%B7%22%5D%20--%3E%20FR%5B%22%E5%8A%A0%20MAC%20%E5%A4%B4%E4%B8%8E%20FCS%22%5D%0A%20%20FR%20--%3E%20WIRE%5B%22%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20WIRE%20--%3E%20FILT%5B%22%E7%9B%AE%E7%9A%84%E8%BF%87%E6%BB%A4%22%5D%0A%20%20FILT%20--%3E%20UP%5B%22%E4%BA%A4%E7%BB%99%E7%B1%BB%E5%9E%8B%E5%AF%B9%E5%BA%94%E7%9A%84%E4%B8%8A%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>帧把「邻机」从物理连通变成可寻址。交换机（下一课）正是学这些地址来转发；路由器则剥到 IP 再决定下一跳，可能换一个全新的 MAC。端到端论证：FCS 只覆盖这一跳，中间任何存储转发节点之后仍要上层校验。</p><p>与进程无关：MAC 命名的是接口，不是<a href="/cs/file-bytestream">文件描述符</a>。进程要等到套接字课才接到传输层端口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Wi-Fi 的关联与 802.11 帧都展开，不引入 VLAN 标签的全部 802.1Q 细节。也不把 MAC 随机化隐私策略写成安全课。冲突如何在共享介质上检测与退避，下一课 CSMA；如何在交换式全双工里消失，也在下一课。</p><p>巨帧与标准 MTU 是接口配置；IP 层的 MTU 发现依赖链路实际能装多少载荷。本课不把巨型帧当默认。</p><p>后课默认：一跳靠 MAC 与帧。共享总线如何避免同时发送，以及交换如何学地址，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧是链路 PDU；MAC 是接口的扁平地址。</li><li>FCS 是一跳努力，代替不了端到端。</li><li>冲突与交换是下一课。</li><li>出处：Metcalfe and Boggs, <em>CACM</em> 1976；IEEE 802.3；Kurose and Ross。</li></ul>',9))])}const P=s(p,[["render",E]]);export{M as __pageData,P as default};
